function permutasi(s) {
  if (s.length === 0) return [""];
  const hasil = new Set();
  for (let i = 0; i < s.length; i++) {
    const sisa = s.slice(0, i) + s.slice(i + 1);
    for (const p of permutasi(sisa)) hasil.add(s[i] + p);
  }
  return [...hasil].sort();
}

