def permutasi(s):
    chars = sorted(s)
    hasil = []
    dipakai = [False] * len(chars)

    def cari(jalur):
        if len(jalur) == len(chars):
            hasil.append("".join(jalur))
            return
        for i, ch in enumerate(chars):
            if dipakai[i]:
                continue
            if i > 0 and chars[i] == chars[i - 1] and not dipakai[i - 1]:
                continue
            dipakai[i] = True
            jalur.append(ch)
            cari(jalur)
            jalur.pop()
            dipakai[i] = False

    cari([])
    return hasil

