import "sort"

func permutasi(s string) []string {
	huruf := []rune(s)
	sort.Slice(huruf, func(i, j int) bool { return huruf[i] < huruf[j] })
	hasil := []string{}
	dipakai := make([]bool, len(huruf))
	sekarang := make([]rune, 0, len(huruf))
	var susun func()
	susun = func() {
		if len(sekarang) == len(huruf) {
			hasil = append(hasil, string(sekarang))
			return
		}
		for i, ch := range huruf {
			// lewati huruf kembar agar permutasi tidak dobel
			if dipakai[i] || (i > 0 && huruf[i] == huruf[i-1] && !dipakai[i-1]) {
				continue
			}
			dipakai[i] = true
			sekarang = append(sekarang, ch)
			susun()
			sekarang = sekarang[:len(sekarang)-1]
			dipakai[i] = false
		}
	}
	susun()
	return hasil
}
